package com.tekwatt.ocpp.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="ocpp_messages")public class OcppMessage{@Id private UUID id;@Column(nullable=false,length=100)private String stationId;@Column(nullable=false,length=10)private String direction;@Column(nullable=false)private Integer messageType;@Column(length=100)private String uniqueId;@Column(length=100)private String action;@Column(nullable=false,columnDefinition="TEXT")private String payload;@Column(nullable=false)private Instant createdAt;protected OcppMessage(){}public OcppMessage(String station,String direction,int type,String unique,String action,String payload){id=UUID.randomUUID();stationId=station;this.direction=direction;messageType=type;uniqueId=unique;this.action=action;this.payload=payload;createdAt=Instant.now();}}
